import test from 'node:test';import assert from 'node:assert/strict';import{createRequire}from'node:module';
const {createMemoryCacheHelper:createMemory,createCacheManagerWithHelper:create}=createRequire(import.meta.url)('../dist/index.js');
test('unsupported/unknown requirements and conflicting flags reject before dispatch',async()=>{const memory=createMemory(),helper={...memory,capabilities:{conditionalWrites:'unsupported',counters:'unsupported'}};let calls=0;helper.set=()=>{calls++;};const db=create(helper);assert.throws(()=>db.set('k',1,{ifAbsent:true,ifPresent:true}),/conditions/);assert.throws(()=>db.set('k',1,{ifAbsent:true}),/unsupported/);assert.throws(()=>db.increment('k'),/unsupported/);assert.equal(calls,0);assert.throws(()=>create({...memory,capabilities:undefined},{policy:{requireCapabilities:['conditionalWrites']}}),/unavailable/);await db.close();});
test('direct helper/facade bounds and counter eviction',async()=>{const helper=createMemory({maxEntries:2,policy:{maxValueBytes:32,maxDepth:2,maxBulk:2}}),db=create(helper,{policy:{maxBulk:2,maxValueBytes:32,maxDepth:2}});assert.throws(()=>helper.set('k','x'.repeat(40)),/byte/);assert.throws(()=>db.set('k',{a:{b:{c:1}}}),/depth/);assert.throws(()=>helper.getMany(['a','b','c']),/bulk/);assert.throws(()=>db.setMany({a:1,b:2,c:3}),/bulk/);helper.increment('a');helper.increment('b');helper.increment('c');assert.equal(helper.stats().entries,2);assert.equal(helper.get('a'),undefined);await db.close();assert.throws(()=>helper.get('a'),/closed/);assert.throws(()=>db.get('a'),/closed/);assert.throws(()=>db.clear(),/closed/);assert.throws(()=>db.native(),/closed/);});
test('producer capacity, failure retry, deadline and close cleanup',async()=>{const helper=createMemory();let ends=0;const close=helper.close.bind(helper);const db=create({...helper,close(){ends++;close();}},{policy:{maxPendingProducers:1}});let release,started;const ready=new Promise(r=>{started=r;});const job=db.remember('a',async({signal})=>{started();await new Promise(r=>{release=r;});assert.equal(signal.aborted,true);return 'late';},{timeoutMs:5});await ready;await assert.rejects(db.remember('b',()=>1),/capacity/);await assert.rejects(job,/cancelled/);await assert.rejects(db.remember('b',()=>1),/capacity/);let closed=false;const closing=db.close().then(()=>{closed=true;});await new Promise(r=>setImmediate(r));assert.equal(closed,false);release();await closing;await db.close();assert.equal(ends,1);const retry=create(createMemory());await assert.rejects(retry.remember('k',()=>{throw Error('dependency offline');}),/offline/);assert.equal(await retry.remember('k',()=>2),2);await retry.close();});
test('waiter abort keeps other subscribers/tenants usable; borrowed helper ownership',async()=>{const helper=createMemory(),a=create(helper,{prefix:'a',policy:{ownHelper:false}}),b=create(helper,{prefix:'b',policy:{ownHelper:false}});let resolve,started;const ready=new Promise(r=>{started=r;}),controller=new AbortController();const first=a.remember('k',async()=>{started();return await new Promise(r=>{resolve=r;});},{signal:controller.signal});await ready;const second=a.remember('k',()=>{throw Error('duplicate');});controller.abort();await assert.rejects(first,/cancelled/);await b.set('k','tenant b');resolve('tenant a');assert.equal(await second,'tenant a');await a.close();assert.equal(await b.get('k'),'tenant b');await b.close();helper.close();});
test('reads and counter results enforce the facade domain; close drains accepted native work',async()=>{const helper=createMemory();let release;const db=create({...helper,get:()=>new Promise(r=>{release=r;})},{policy:{maxValueBytes:8,ownHelper:false}});const read=db.get('k');const rejected=assert.rejects(read,/byte/);let closed=false;const closing=db.close().then(()=>{closed=true;});await new Promise(r=>setImmediate(r));assert.equal(closed,false);release('oversized value');await rejected;await closing;const unsafe=create({...helper,increment:()=>9007199254740992},{policy:{ownHelper:false}});assert.throws(()=>unsafe.increment('k'),/safe integer/);await unsafe.close();helper.close();assert.throws(()=>create({}),/required contract/);});
